/**
 * Main view "Voice conversation": one-tap full-duplex call with a realtime audio model served by dsh-dgx-audio.
 * Iteration 1 (audio only): readiness, start, listening/speaking state, reply captions, a two-lane timeline on one
 * clock (you / model, 1-second decision cells), mute, stop reply, interruption mode, end, details.
 */

import { useEffect, useRef, useState, useSyncExternalStore } from 'react'
import type { AudioRoutesStore } from '../audio-routes.ts'
import { format, type AudioKitKey } from '../locale.ts'
import type { TurnMode, VoiceLiveSession, VoiceSnapshot } from './live-session.ts'
import css from './voice.module.css'

export interface VoiceCandidate { readonly provider: string, readonly model: string, readonly label: string, readonly activation?: string | undefined }

export interface VoicePageFace {
  readonly session: VoiceLiveSession
  readonly routes: AudioRoutesStore
  /** Creates the audio conversation the call belongs to and returns its id. */
  createSession(candidate: VoiceCandidate): Promise<string>
  openSession(sessionId: string): void
  openAudioModels(): void
}

const WINDOW_MS = 16000

function candidatesOf(routes: ReturnType<AudioRoutesStore['getSnapshot']>): VoiceCandidate[] {
  const out: VoiceCandidate[] = []
  for (const route of routes.routes) {
    for (const model of route.models) {
      if (model.mode !== 'realtime') continue
      const activation = (model as { activation?: { state?: string } }).activation?.state
      out.push({ provider: route.provider, model: model.id, label: model.name ?? model.id, activation })
    }
  }
  // Ready first; MiniCPM-o first among equals (the demo model).
  return out.sort((a, b) => Number(b.activation === 'ready' || b.activation === undefined) - Number(a.activation === 'ready' || a.activation === undefined) || Number(/minicpm/i.test(b.label)) - Number(/minicpm/i.test(a.label)))
}

function clock(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`
}

function drawTimeline(canvas: HTMLCanvasElement, snap: VoiceSnapshot, t: (key: AudioKitKey) => string): void {
  const width = canvas.clientWidth
  const height = 140
  const dpr = window.devicePixelRatio || 1
  if (canvas.width !== Math.round(width * dpr)) { canvas.width = Math.round(width * dpr); canvas.height = Math.round(height * dpr) }
  const ctx = canvas.getContext('2d')
  if (ctx === null) return
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  const style = getComputedStyle(canvas)
  const token = (name: string, fallback: string) => style.getPropertyValue(name).trim() || fallback
  const label = token('--dsw-alias-label-primary', '#0f1115')
  const muted = token('--dsw-alias-label-tertiary', '#81858c')
  const border = token('--dsw-alias-border-l2', 'rgba(0,0,0,.1)')
  const link = token('--dsw-alias-link', 'rgb(65,118,230)')
  const ok = token('--dsw-alias-state-success-primary', 'rgb(34,197,94)')
  const err = token('--dsw-alias-state-error-primary', 'rgb(236,19,19)')
  const layer = token('--dsw-alias-bg-layer-2', 'rgba(0,0,0,.03)')
  ctx.clearRect(0, 0, width, height)
  const now = performance.now()
  const labelW = 52
  const plotW = Math.max(10, width - labelW)
  const x = (at: number) => labelW + plotW - ((now - at) / WINDOW_MS) * plotW
  const lanes = [{ name: t('voiceLaneYou'), y: 6 }, { name: t('voiceLaneModel'), y: 58 }]
  const laneH = 44
  // 1-second cells on the model lane, tinted by the latest decision in that second (fallback: model audio present)
  const firstSec = Math.floor((now - WINDOW_MS) / 1000)
  for (let sec = firstSec; sec * 1000 <= now; sec++) {
    const x0 = Math.max(labelW, x(sec * 1000))
    const x1 = Math.min(width, x((sec + 1) * 1000))
    if (x1 - x0 < 2) continue
    const inSec = (at: number) => at >= sec * 1000 && at < (sec + 1) * 1000
    const decision = [...snap.decisions].reverse().find(d => inSec(d.at))?.decision
    const spoke = decision === 'speak' || (decision === undefined && snap.levels.some(l => inSec(l.at) && l.model > 0))
    ctx.fillStyle = layer
    ctx.fillRect(x0 + 1, lanes[0]!.y, x1 - x0 - 2, laneH)
    ctx.globalAlpha = decision === undefined && !spoke ? 0.35 : 0.18
    ctx.fillStyle = spoke ? link : ok
    ctx.fillRect(x0 + 1, lanes[1]!.y, x1 - x0 - 2, laneH)
    ctx.globalAlpha = 1
  }
  const barW = Math.max(1.5, plotW / (WINDOW_MS / 100) - 1)
  for (const sample of snap.levels) {
    const bx = x(sample.at)
    if (bx < labelW) continue
    if (sample.user > 0.01) { const bh = Math.max(2, sample.user * (laneH - 8)); ctx.globalAlpha = 0.75; ctx.fillStyle = label; ctx.fillRect(bx, lanes[0]!.y + (laneH - bh) / 2, barW, bh); ctx.globalAlpha = 1 }
    if (sample.model > 0) { const bh = Math.max(3, sample.model * (laneH - 12)); ctx.fillStyle = link; ctx.fillRect(bx, lanes[1]!.y + (laneH - bh) / 2, barW, bh) }
  }
  for (const at of snap.interruptions) {
    const bx = x(at)
    if (bx < labelW) continue
    ctx.fillStyle = err
    ctx.fillRect(bx, lanes[0]!.y, 2, lanes[1]!.y + laneH - lanes[0]!.y)
  }
  ctx.fillStyle = muted
  ctx.font = `500 12px ${style.fontFamily}`
  for (const lane of lanes) ctx.fillText(lane.name, 0, lane.y + laneH / 2 + 4)
  ctx.strokeStyle = border
  ctx.beginPath(); ctx.moveTo(labelW, height - 16.5); ctx.lineTo(width, height - 16.5); ctx.stroke()
  ctx.font = `400 10px ${style.fontFamily}`
  for (let ago = 0; ago <= 15; ago += 5) {
    const tx = width - (ago * 1000 / WINDOW_MS) * plotW
    ctx.fillRect(tx - 1, height - 16, 1, 4)
    ctx.fillText(ago === 0 ? t('voiceNow') : `−${ago} s`, Math.max(labelW, Math.min(tx - (ago === 0 ? 22 : 12), width - 26)), height - 3)
  }
}

export function VoicePage(props: any) {
  const t = (key: AudioKitKey, values?: Record<string, string>) => format(props.t(key), values)
  const face: VoicePageFace = props.voicePage
  const snap = useSyncExternalStore(face.session.subscribe, face.session.getSnapshot)
  const routes = useSyncExternalStore(face.routes.subscribe, face.routes.getSnapshot)
  const [sessionId, setSessionId] = useState<string>()
  const [busy, setBusy] = useState(false)
  const [details, setDetails] = useState(false)
  const [startError, setStartError] = useState<string>()
  const canvas = useRef<HTMLCanvasElement>(null)
  const candidates = candidatesOf(routes)
  const candidate = candidates[0]
  const ready = candidate !== undefined && (candidate.activation === undefined || candidate.activation === 'ready')
  const inCall = snap.phase === 'starting' || snap.phase === 'live' || snap.phase === 'closing'

  useEffect(() => { void face.routes.refresh() }, [])
  useEffect(() => { if (canvas.current !== null && inCall) drawTimeline(canvas.current, snap, t) })

  const start = async () => {
    if (candidate === undefined) return
    setBusy(true)
    setStartError(undefined)
    try {
      const id = await face.createSession(candidate)
      setSessionId(id)
      await face.session.start({ sessionId: id, provider: candidate.provider, model: candidate.model, turnMode: snap.turnMode })
    } catch (error) {
      setStartError(error instanceof Error ? error.message : String(error))
    } finally {
      setBusy(false)
    }
  }

  const stateLabel = snap.muted ? t('voiceStateMuted')
    : snap.phase === 'starting' ? t('voiceStateConnecting')
      : snap.speaking ? t('voiceStateAnswering')
        : snap.userSpeaking ? t('voiceStateYou')
          : snap.waitingForUser ? t('voiceStateWaiting')
            : t('voiceStateListening')
  const stateSub = snap.muted ? t('voiceSubMuted')
    : snap.speaking ? (snap.turnMode === 'server-vad' ? t('voiceSubInterrupt') : t('voiceSubNative'))
      : snap.waitingForUser ? t('voiceSubWaiting')
        : snap.turnMode === 'server-vad' ? t('voiceSubListenVad') : t('voiceSubDecide')
  const pulseClass = snap.muted ? css.pulseOff : snap.speaking ? css.pulseSpeak : css.pulse

  if (!inCall) {
    return (
      <div className={css.page} data-testid="dsh-voice-page" data-phase={snap.phase}>
        <header className={css.head}>
          <div>
            <h1 className={css.title}>{t('voiceTitle')}</h1>
            <p className={css.lead}>{t('voiceLead')}</p>
          </div>
          <button type="button" className={css.secondary} onClick={() => { void face.routes.refresh() }}>{t('voiceRefresh')}</button>
        </header>
        <section className={css.card}>
          {candidate === undefined
            ? (
              <div className={css.stack}>
                <p className={css.strong}>{t('voiceNoModel')}</p>
                <p className={css.muted}>{t('voiceNoModelHelp')}</p>
                <div><button type="button" className={css.secondary} onClick={() => { face.openAudioModels() }}>{t('voiceOpenModels')}</button></div>
              </div>
            )
            : (
              <div className={css.stack}>
                <div className={css.row}>
                  <span className={ready ? css.dotOk : css.dotWarn} />
                  <span className={css.strong}>{candidate.label}</span>
                  <span className={css.badge}>{ready ? t('voiceReady') : t('voiceNotReady', { state: candidate.activation ?? '' })}</span>
                </div>
                <fieldset className={css.modes} disabled={busy}>
                  <legend className={css.muted}>{t('voiceModeLegend')}</legend>
                  {(['server-vad', 'native-duplex'] as TurnMode[]).map(mode => (
                    <label key={mode} className={css.mode}>
                      <input type="radio" name="dsh-voice-turn" value={mode} checked={snap.turnMode === mode} onChange={() => { face.session.setTurnMode(mode) }} data-testid={`dsh-voice-mode-${mode}`} />
                      <span><span className={css.strong}>{mode === 'server-vad' ? t('voiceModeVad') : t('voiceModeNative')}</span><span className={css.help}>{mode === 'server-vad' ? t('voiceModeVadHelp') : t('voiceModeNativeHelp')}</span></span>
                    </label>
                  ))}
                </fieldset>
                <div className={css.row}>
                  <button type="button" className={css.primary} disabled={!ready || busy} onClick={() => { void start() }} data-testid="dsh-voice-start">{busy ? t('voiceStarting') : t('voiceStart')}</button>
                  <span className={css.muted}>{t('voiceHeadphones')}</span>
                </div>
                {!ready ? <p className={css.warn}>{t('voiceNotReadyHelp')}</p> : null}
              </div>
            )}
          {(startError ?? snap.error) !== undefined && snap.phase !== 'closed'
            ? <p className={css.error} role="alert" data-testid="dsh-voice-error">{t('voiceError', { message: startError ?? snap.error ?? '' })}</p>
            : null}
        </section>
        {snap.phase === 'closed' && sessionId !== undefined
          ? (
            <section className={css.card} data-testid="dsh-voice-ended">
              <div className={css.stack}>
                <p className={css.strong}>{t('voiceEnded', { count: String(snap.interruptions.length) })}</p>
                <p className={css.muted}>{t('voiceEndedHelp')}</p>
                <div className={css.row}>
                  <button type="button" className={css.secondary} onClick={() => { face.openSession(sessionId) }}>{t('voiceOpenConversation')}</button>
                </div>
              </div>
            </section>
          )
          : null}
      </div>
    )
  }

  return (
    <div className={css.call} data-testid="dsh-voice-call" data-phase={snap.phase} data-speaking={snap.speaking} data-muted={snap.muted} data-response-active={snap.responseActive} data-playback-gaps={snap.playbackGaps} data-waiting-for-user={snap.waitingForUser} data-held-replies={snap.heldReplies}>
      <header className={css.callHead}>
        <div className={css.row}>
          <h1 className={css.callTitle}>{t('voiceTitle')}</h1>
          <span className={css.badge}>{candidate?.label}</span>
          <span className={css.badgeMono} data-testid="dsh-voice-timer">{clock(snap.startedAt === undefined ? 0 : performance.now() - snap.startedAt)}</span>
        </div>
        <button type="button" className={css.secondary} aria-expanded={details} onClick={() => { setDetails(!details) }}>{t('voiceDetails')}</button>
      </header>
      <div className={css.callBody}>
        <div>
          <div className={css.state} aria-live="polite" data-testid="dsh-voice-state"><span className={pulseClass} />{stateLabel}</div>
          <div className={css.muted}>{stateSub}</div>
        </div>
        <div className={css.lanes}>
          <div className={css.lanesHead}><span>{t('voiceTimelineHint')}</span></div>
          <canvas ref={canvas} className={css.canvas} height={140} aria-label={t('voiceTimelineHint')} />
        </div>
        <div className={css.captions} aria-live="polite" data-testid="dsh-voice-captions">
          {snap.previousCaption !== undefined ? <div className={css.capPrev}>{snap.previousCaption.text}</div> : null}
          <div className={css.capNow}>
            {snap.caption === undefined ? <span className={css.muted}>{t('voiceCaptionEmpty')}</span> : snap.caption.text}
            {snap.caption?.stopped ? <span className={css.stopped}>{t('voiceStopped')}</span> : null}
          </div>
        </div>
        {snap.warnings.length > 0 ? <p className={css.warn}>{t('voiceWarnings', { codes: snap.warnings.join(', ') })}</p> : null}
        {details
          ? (
            <table className={css.details}>
              <tbody>
                <tr><td>{t('voiceDetailFrames')}</td><td>{snap.framesSent} / {snap.framesAccepted}</td></tr>
                <tr><td>{t('voiceDetailFirstAudio')}</td><td>{snap.firstAudioMs === undefined ? '—' : `${(snap.firstAudioMs / 1000).toFixed(1)} s`}</td></tr>
                <tr><td>{t('voiceDetailInterrupt')}</td><td>{snap.lastInterruptMs === undefined ? '—' : `${(snap.lastInterruptMs / 1000).toFixed(2)} s`}</td></tr>
                <tr><td>{t('voiceDetailGaps')}</td><td>{snap.playbackGaps === 0 ? '0' : `${snap.playbackGaps} · ${(snap.playbackGapMs / 1000).toFixed(1)} s`}</td></tr>
                <tr><td>{t('voiceDetailBuffer')}</td><td>{`${(snap.playbackBufferMs / 1000).toFixed(2)} s`}</td></tr>
                <tr><td>{t('voiceDetailHeld')}</td><td>{snap.heldReplies}</td></tr>
                <tr><td>{t('voiceDetailTurn')}</td><td>{snap.turnReported ?? snap.turnMode}</td></tr>
                <tr><td>{t('voiceDetailAudio')}</td><td>AEC · NS · AGC</td></tr>
              </tbody>
            </table>
          )
          : null}
      </div>
      <footer className={css.controls}>
        <button type="button" className={snap.muted ? css.toggleOn : css.secondary} aria-pressed={snap.muted} onClick={() => { face.session.setMuted(!snap.muted) }} data-testid="dsh-voice-mute">{snap.muted ? t('voiceUnmute') : t('voiceMute')}</button>
        <button type="button" className={css.secondary} disabled={!snap.speaking} onClick={() => { face.session.stopReply() }} data-testid="dsh-voice-stop">{t('voiceStopReply')}</button>
        <span className={css.badge}>{snap.turnMode === 'server-vad' ? t('voiceModeVad') : t('voiceModeNative')}</span>
        <button type="button" className={css.danger} onClick={() => { void face.session.end() }} data-testid="dsh-voice-end">{t('voiceEnd')}</button>
      </footer>
    </div>
  )
}

export function VoiceIcon(props: { size?: number, active?: boolean }) {
  const size = props.size ?? 16
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none" aria-hidden="true" data-testid="dsh-voice-sidebar-icon" data-active={props.active === true}>
      <rect x="5.5" y="1.5" width="5" height="8.5" rx="2.5" stroke="currentColor" strokeWidth="1.3" />
      <path d="M3 7.5a5 5 0 0 0 10 0M8 12.5v2" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
    </svg>
  )
}
