/**
 * Shared, read-only view of the audio routes the dsh-dgx-audio host plugin serves, fetched from its
 * capability document (`GET /api/dsh-dgx-audio/v1/capabilities`, CONTRACT §2). Relative URLs work on
 * both Web (`http://…/api`) and Desktop (`dsh-app://app/api`). Nothing here contacts a model server.
 */

export type CapabilityState = 'unsupported' | 'untested' | 'declared' | 'advertised' | 'verified'

export interface CapabilityView {
  readonly state: CapabilityState
  readonly detail?: string | null
  readonly observedDelivery?: string | null
}

export interface AudioModelView {
  readonly id: string
  readonly name?: string
  readonly mode: 'chat' | 'transcribe' | 'realtime'
  readonly output?: { readonly text?: boolean, readonly audio?: boolean }
  readonly capabilities?: Readonly<Record<string, CapabilityView>>
}

export interface AudioRouteView {
  readonly provider: string
  readonly displayName?: string
  readonly baseURL: string
  readonly authentication?: string
  readonly credentialPresent?: boolean
  readonly models: readonly AudioModelView[]
}

export interface AudioRoutesSnapshot {
  readonly status: 'loading' | 'ready' | 'absent' | 'error'
  readonly configured: boolean
  readonly routes: readonly AudioRouteView[]
  readonly message?: string
}

const CAPABILITIES_PATH = '/api/dsh-dgx-audio/v1/capabilities'

/** A tiny external store so every chip and the settings card share one fetch. */
export class AudioRoutesStore {
  private snapshot: AudioRoutesSnapshot = { status: 'loading', configured: false, routes: [] }
  private readonly listeners = new Set<() => void>()
  private inflight: Promise<void> | undefined
  private disposed = false

  getSnapshot = (): AudioRoutesSnapshot => this.snapshot

  subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  dispose(): void {
    this.disposed = true
    this.listeners.clear()
  }

  /** Re-read the capability document (after settings changes, probes or reconnects). */
  refresh(): Promise<void> {
    if (this.inflight !== undefined) return this.inflight
    this.inflight = this.load().finally(() => { this.inflight = undefined })
    return this.inflight
  }

  /** Providers whose models belong to the audio adapter. */
  providers(): ReadonlySet<string> {
    return new Set(this.snapshot.routes.map(route => route.provider))
  }

  private publish(next: AudioRoutesSnapshot): void {
    if (this.disposed) return
    this.snapshot = next
    for (const listener of this.listeners) listener()
  }

  private async load(): Promise<void> {
    try {
      const response = await fetch(CAPABILITIES_PATH, { credentials: 'include' })
      if (response.status === 404) {
        this.publish({ status: 'absent', configured: false, routes: [] })
        return
      }
      if (!response.ok) {
        this.publish({ status: 'error', configured: false, routes: this.snapshot.routes, message: `HTTP ${response.status}` })
        return
      }
      const body = await response.json() as { configured?: boolean, routes?: AudioRouteView[] }
      this.publish({ status: 'ready', configured: body.configured === true, routes: Array.isArray(body.routes) ? body.routes : [] })
    } catch (error) {
      this.publish({ status: 'error', configured: false, routes: this.snapshot.routes, message: error instanceof Error ? error.message : String(error) })
    }
  }
}

export interface ProbeResult {
  readonly ok: boolean
  readonly message: string
}

/** Explicit, user-initiated reachability check (`GET {baseURL}/models` on the host; no inference). */
export async function probeReachability(provider: string, model: string): Promise<ProbeResult> {
  try {
    const response = await fetch(`${CAPABILITIES_PATH}/probe`, {
      method: 'POST',
      credentials: 'include',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ provider, model, checks: ['reachability'] }),
    })
    const body = await response.json().catch(() => undefined) as {
      ok?: boolean
      error?: { code?: string, message?: string }
      probe?: { reachability?: { ok?: boolean, status?: number, modelListed?: boolean, ms?: number, error?: { code?: string, message?: string } } }
    } | undefined
    if (!response.ok || body?.ok === false) {
      return { ok: false, message: body?.error?.message ?? body?.error?.code ?? `HTTP ${response.status}` }
    }
    const reach = body?.probe?.reachability
    if (reach?.ok !== true) {
      return { ok: false, message: reach?.error?.message ?? (reach?.status !== undefined ? `HTTP ${reach.status}` : 'unreachable') }
    }
    return { ok: true, message: `${reach.ms ?? '?'} ms${reach.modelListed === false ? ' · model not listed by the server' : ''}` }
  } catch (error) {
    return { ok: false, message: error instanceof Error ? error.message : String(error) }
  }
}
