/**
 * Composer chip for the `conversation.input.left` slot: shown only when the session's selected model belongs to
 * the audio adapter while the session is not in the "DGX audio (no tools)" preset. Upstream refuses a preset
 * switch once a session has history, so a started session gets a new conversation in the same workspace with the
 * same model; a blank session is switched in place. Normal sessions (non-audio models) render nothing.
 */

import { useState, useSyncExternalStore } from 'react'
import type { AudioRoutesStore } from './audio-routes.ts'
import { format, type AudioKitKey } from './locale.ts'
import css from './kit.module.css'

export const AUDIO_PRESET_ID = 'dgx-audio'

export interface AudioModeActions {
  switchBlank(sessionId: string): Promise<void>
  startAudioConversation(sessionId: string, provider: string, model: string): Promise<void>
}

interface ModelSelection { provider: string, model: string }

export function AudioModeChip(props: any) {
  const t = (key: AudioKitKey, values?: Record<string, string>) => format(props.t(key), values)
  const store: AudioRoutesStore = props.audioRoutes
  const actions: AudioModeActions = props.audioModeActions
  const routes = useSyncExternalStore(store.subscribe, store.getSnapshot)
  const preset = props.useProjection('agentPreset') as string | null | undefined
  const selection = props.useProjection('modelSelection', (value: any) => value?.next ?? value?.lastUsed ?? null) as ModelSelection | null
  const blank = props.useSessions((state: any) => state.byId?.[props.sessionId]?.blank === true) as boolean
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const audioProvider = selection !== null && routes.routes.some(route => route.provider === selection.provider)
  if (!audioProvider || preset === AUDIO_PRESET_ID || preset === undefined) return null

  const label = blank ? t('chipUseAudioMode') : t('chipNewAudioConversation')
  const hint = blank ? t('chipHintBlank') : t('chipHintStarted')
  const run = async () => {
    setBusy(true)
    setError(null)
    try {
      if (blank) await actions.switchBlank(props.sessionId)
      else await actions.startAudioConversation(props.sessionId, selection.provider, selection.model)
    } catch (reason) {
      setError(t('chipFailed', { message: reason instanceof Error ? reason.message : String(reason) }))
    } finally {
      setBusy(false)
    }
  }
  return (
    <span className={css.chipWrap}>
      <button
        type="button"
        className={css.chip}
        data-testid="dsh-audio-mode-chip"
        title={hint}
        aria-label={`${label}. ${hint}`}
        disabled={busy}
        onClick={() => { void run() }}
      >
        <span className={css.chipDot} aria-hidden="true" />
        {busy ? t('chipWorking') : label}
      </button>
      {error !== null ? <span className={css.chipError} role="status">{error}</span> : null}
    </span>
  )
}
