/**
 * Voice conversation session for the release-kit voice page: microphone → host live route, host feed → speaker.
 *
 * Talks only to the dsh-dgx-audio host routes (CONTRACT §3 feed, §5 live): `live/open`, `live/append`, `live/control`,
 * `live/close` and `GET events`. Nothing here contacts a model server. The microphone is opened (and its permission
 * granted) before `live/open`, so a refused permission never leaves a backend session open. While muted, silence frames
 * keep flowing: a native-duplex model needs a continuous frame clock, and the host closes idle sessions after 15 s.
 */

const PREFIX = '/api/dsh-dgx-audio/v1'
const FRAME_SAMPLES = 3200 // 200 ms at 16 kHz
const TIMELINE_KEEP_MS = 24000
// While the reply is still open on the server, a gap between audio chunks keeps "answering" for this long.
const SPEAKING_HOLD_MS = 1200
// Reply audio starts this far ahead of the clock; each gap (audio arrived late) adds a step, up to the maximum.
const PLAYBACK_BUFFER_START_S = 0.3
const PLAYBACK_BUFFER_STEP_S = 0.25
const PLAYBACK_BUFFER_MAX_S = 1.0
// After Stop reply the page waits for the user's next turn to END before it plays replies again: replies the model starts
// while the user is still talking are not answers yet (DEMO-VOICE-3: MiniCPM-o 4.5 started "So we…" as the user began).
// The turn end is the server's speech stopped/committed event, or locally: input at least RESUME_LEVEL for RESUME_MS, then
// below it for TURN_END_MS.
const RESUME_LEVEL = 0.2
const RESUME_MS = 300
const TURN_END_MS = 700

export type VoicePhase = 'idle' | 'starting' | 'live' | 'closing' | 'closed' | 'error'
export type TurnMode = 'server-vad' | 'native-duplex'

export interface LevelSample { readonly at: number, readonly user: number, readonly model: number }
export interface DecisionMark { readonly at: number, readonly decision: 'listen' | 'speak' | 'overlap' }
export interface CaptionLine { readonly responseId: string, readonly text: string, readonly stopped: boolean }

export interface VoiceSnapshot {
  readonly phase: VoicePhase
  readonly error?: string | undefined
  readonly startedAt?: number | undefined
  readonly muted: boolean
  readonly turnMode: TurnMode
  readonly turnReported?: string | undefined
  readonly speaking: boolean
  readonly userSpeaking: boolean
  readonly levels: readonly LevelSample[]
  readonly decisions: readonly DecisionMark[]
  readonly interruptions: readonly number[]
  readonly caption?: CaptionLine | undefined
  readonly previousCaption?: CaptionLine | undefined
  readonly framesSent: number
  readonly framesAccepted: number
  /** Interruption (speech detected, or Stop reply clicked) → the server cancelled the reply. */
  readonly lastInterruptMs?: number | undefined
  /** End of the user's speech → first audio of the latest reply. */
  readonly firstAudioMs?: number | undefined
  /** A reply is open on the server (created, not yet completed or cancelled). */
  readonly responseActive: boolean
  /** Reply audio that ran out before the next chunk arrived: count and total silence. */
  readonly playbackGaps: number
  readonly playbackGapMs: number
  /** Current reply playback buffer (grows after gaps). */
  readonly playbackBufferMs: number
  /** Stop reply was pressed and the user has not spoken since: new replies are cancelled, not played. */
  readonly waitingForUser: boolean
  /** Replies the model started while waiting for the user (cancelled, not played). */
  readonly heldReplies: number
  readonly warnings: readonly string[]
}

export interface StartOptions {
  readonly sessionId: string
  readonly provider: string
  readonly model: string
  readonly turnMode: TurnMode
}

interface Stream {
  readonly id: string
  sampleRate: number
  epoch: number
  cursor: number // AudioContext time where the next chunk starts
  startedAt?: number | undefined // AudioContext time of the first sample scheduled since the last flush
  playedBaseMs: number // audio heard before the last flush
  playedMs: number // last value acknowledged to the host
  sources: Set<AudioBufferSourceNode>
  ended: boolean
}

const TAP_SOURCE = `class VoiceTap extends AudioWorkletProcessor {
  process(inputs) { const ch = inputs[0] && inputs[0][0]; if (ch) this.port.postMessage(ch.slice(0)); return true }
}
registerProcessor('dsh-voice-tap', VoiceTap)`

function pcm16(samples: Float32Array): Uint8Array {
  const out = new Uint8Array(samples.length * 2)
  const view = new DataView(out.buffer)
  for (let i = 0; i < samples.length; i++) {
    const s = Math.max(-1, Math.min(1, samples[i]!))
    view.setInt16(i * 2, s < 0 ? s * 0x8000 : s * 0x7fff, true)
  }
  return out
}

function rms(samples: Float32Array): number {
  let sum = 0
  for (let i = 0; i < samples.length; i++) sum += samples[i]! * samples[i]!
  return Math.sqrt(sum / Math.max(1, samples.length))
}

async function postJson(path: string, body: unknown): Promise<any> {
  const response = await fetch(path, { method: 'POST', credentials: 'include', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) })
  const json = await response.json().catch(() => ({ ok: false, error: { code: `HTTP_${response.status}`, message: response.statusText } }))
  if (!response.ok || json?.ok === false) {
    const error = new Error(json?.error?.message ?? `HTTP ${response.status}`) as Error & { code?: string }
    error.code = json?.error?.code
    throw error
  }
  return json
}

export class VoiceLiveSession {
  private snapshot: VoiceSnapshot = { phase: 'idle', muted: false, turnMode: 'server-vad', speaking: false, userSpeaking: false, levels: [], decisions: [], interruptions: [], framesSent: 0, framesAccepted: 0, responseActive: false, playbackGaps: 0, playbackGapMs: 0, playbackBufferMs: PLAYBACK_BUFFER_START_S * 1000, waitingForUser: false, heldReplies: 0, warnings: [] }
  private readonly listeners = new Set<() => void>()
  private liveId?: string | undefined
  private sessionId?: string | undefined
  private stream?: MediaStream | undefined
  private captureContext?: AudioContext | undefined
  private captureNode?: AudioNode | undefined
  private playbackContext?: AudioContext | undefined
  private feedAbort?: AbortController | undefined
  private pending: Float32Array[] = []
  private pendingLength = 0
  private seq = 0
  private sendChain: Promise<void> = Promise.resolve()
  private readonly streams = new Map<string, Stream>()
  private readonly texts = new Map<string, string>()
  private activeResponse?: string | undefined
  private lastStreamId?: string | undefined
  private replyOpen = false
  private readonly heldIds = new Set<string>()
  private loudMs = 0
  private quietMs = 0
  private userTurnSeen = false
  private bufferS = PLAYBACK_BUFFER_START_S
  private userLevel = 0
  private modelLevelUntil = 0
  private modelLevel = 0
  private speechEndedAt?: number | undefined
  private bargeAt?: number | undefined
  private ackTimer?: ReturnType<typeof setInterval> | undefined
  private tickTimer?: ReturnType<typeof setInterval> | undefined

  getSnapshot = (): VoiceSnapshot => this.snapshot

  subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  private set(patch: Partial<VoiceSnapshot>): void {
    this.snapshot = { ...this.snapshot, ...patch }
    for (const listener of this.listeners) listener()
  }

  setTurnMode(mode: TurnMode): void {
    if (this.snapshot.phase === 'live' || this.snapshot.phase === 'starting') return
    this.set({ turnMode: mode })
  }

  setMuted(muted: boolean): void {
    this.set({ muted })
  }

  async start(options: StartOptions): Promise<void> {
    if (this.snapshot.phase === 'starting' || this.snapshot.phase === 'live') return
    this.reset(options.turnMode)
    this.set({ phase: 'starting', error: undefined })
    try {
      // Permission first: a refused microphone must not leave a backend session open.
      this.stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true, channelCount: 1 }, video: false })
      this.playbackContext = new AudioContext()
      await this.playbackContext.resume()
      this.sessionId = options.sessionId
      this.openFeed(options.sessionId)
      const opened = await postJson(`${PREFIX}/live/open`, {
        sessionId: options.sessionId,
        provider: options.provider,
        model: options.model,
        ...(options.turnMode === 'server-vad' ? { turnDetection: 'server_vad' } : {}),
      })
      this.liveId = String(opened.liveId)
      await this.openCapture()
      this.ackTimer = setInterval(() => { this.sendAcks() }, 500)
      this.tickTimer = setInterval(() => { this.tick() }, 100)
      this.set({ phase: 'live', startedAt: performance.now() })
    } catch (error) {
      const code = (error as { code?: string }).code
      await this.teardown()
      this.set({ phase: 'error', error: code === undefined ? String((error as Error).message ?? error) : `${code}: ${(error as Error).message}` })
    }
  }

  /**
   * Stop the reply that is playing now. Local audio stops at once, also when the server has already finished generating
   * and only playback remains. A reply still open on the server is cancelled with `cancel-response` (not `barge-in`,
   * which tells a duplex model the user is taking the turn and, observed on MiniCPM-o 4.5, leads it to start a new reply
   * into the silence). The host then gets a truncating playback ack, so the model keeps only what was heard. Until the
   * user speaks again, replies the model starts are cancelled and not played.
   */
  stopReply(): void {
    const liveId = this.liveId
    const target = this.activeResponse ?? this.lastStreamId
    if (this.snapshot.phase !== 'live' || liveId === undefined || target === undefined) return
    const context = this.playbackContext
    const stream = this.streams.get(target)
    const heardMs = stream === undefined || context === undefined ? undefined : this.heardMs(stream, context)
    for (const id of this.streams.keys()) this.flushPlayback(id)
    this.replyOpen = false
    this.markStopped(target)
    this.loudMs = 0
    this.quietMs = 0
    this.userTurnSeen = false
    this.set({ interruptions: [...this.snapshot.interruptions, performance.now()], speaking: false, waitingForUser: true })
    const cancel = this.activeResponse !== undefined
    const clickedAt = performance.now()
    // Chunks of the stopped reply still on their way (the host delivers progressively) are dropped.
    this.heldIds.add(target)
    const control = `${PREFIX}/live/control?liveId=${encodeURIComponent(liveId)}`
    void (async () => {
      if (cancel) {
        const reply = await postJson(control, { type: 'cancel-response', responseId: target, wait: true, waitMs: 3000 }).catch(() => undefined)
        if (reply?.outcome === 'cancelled') this.set({ lastInterruptMs: Math.round(performance.now() - clickedAt) })
      }
      if (heardMs !== undefined) {
        if (stream !== undefined) stream.playedMs = heardMs
        await postJson(control, { type: 'playback-ack', responseId: target, playedMs: heardMs, truncate: true }).catch(() => {})
      }
    })()
  }

  /** A reply that starts while waiting for the user: cancel it on the server and never play it. */
  private holdReply(id: string): void {
    if (this.heldIds.has(id)) return
    this.heldIds.add(id)
    this.set({ heldReplies: this.snapshot.heldReplies + 1 })
    const liveId = this.liveId
    if (liveId !== undefined) void postJson(`${PREFIX}/live/control?liveId=${encodeURIComponent(liveId)}`, { type: 'cancel-response', responseId: id }).catch(() => {})
  }

  /** The user's turn after Stop reply has ended: replies created from now on are played again. */
  private userTurnEnded(): void {
    if (!this.snapshot.waitingForUser) return
    this.loudMs = 0
    this.quietMs = 0
    this.userTurnSeen = false
    this.set({ waitingForUser: false })
  }

  async end(): Promise<void> {
    if (this.snapshot.phase !== 'live' && this.snapshot.phase !== 'starting') return
    this.set({ phase: 'closing' })
    for (const id of this.streams.keys()) this.flushPlayback(id)
    const liveId = this.liveId
    await this.stopCapture()
    if (liveId !== undefined) await postJson(`${PREFIX}/live/close?liveId=${encodeURIComponent(liveId)}`, {}).catch(() => {})
    await this.teardown()
    this.set({ phase: 'closed', speaking: false, userSpeaking: false })
  }

  dispose(): void {
    void this.end()
    this.listeners.clear()
  }

  private reset(turnMode: TurnMode): void {
    this.streams.clear()
    this.texts.clear()
    this.activeResponse = undefined
    this.lastStreamId = undefined
    this.replyOpen = false
    this.heldIds.clear()
    this.loudMs = 0
    this.quietMs = 0
    this.userTurnSeen = false
    this.bufferS = PLAYBACK_BUFFER_START_S
    this.seq = 0
    this.pending = []
    this.pendingLength = 0
    this.speechEndedAt = undefined
    this.bargeAt = undefined
    this.snapshot = { phase: 'idle', muted: false, turnMode, speaking: false, userSpeaking: false, levels: [], decisions: [], interruptions: [], framesSent: 0, framesAccepted: 0, responseActive: false, playbackGaps: 0, playbackGapMs: 0, playbackBufferMs: PLAYBACK_BUFFER_START_S * 1000, waitingForUser: false, heldReplies: 0, warnings: [] }
  }

  private async openCapture(): Promise<void> {
    const context = new AudioContext({ sampleRate: 16000 })
    this.captureContext = context
    const source = context.createMediaStreamSource(this.stream!)
    const onFrame = (samples: Float32Array) => { this.onCapture(samples) }
    try {
      const url = URL.createObjectURL(new Blob([TAP_SOURCE], { type: 'application/javascript' }))
      await context.audioWorklet.addModule(url)
      URL.revokeObjectURL(url)
      const node = new AudioWorkletNode(context, 'dsh-voice-tap')
      node.port.onmessage = (event: MessageEvent<Float32Array>) => { onFrame(event.data) }
      source.connect(node)
      this.captureNode = node
    } catch {
      const processor = context.createScriptProcessor(2048, 1, 1)
      processor.onaudioprocess = (event) => { onFrame(new Float32Array(event.inputBuffer.getChannelData(0))) }
      source.connect(processor)
      processor.connect(context.destination)
      this.captureNode = processor
    }
    await context.resume()
  }

  private onCapture(samples: Float32Array): void {
    if (this.snapshot.phase !== 'live' && this.snapshot.phase !== 'starting') return
    const level = this.snapshot.muted ? 0 : Math.min(1, rms(samples) * 6)
    this.userLevel = Math.max(this.userLevel * 0.6, level)
    if (this.snapshot.waitingForUser) {
      const ms = (samples.length / 16000) * 1000
      if (level >= RESUME_LEVEL) { this.loudMs += ms; this.quietMs = 0; if (this.loudMs >= RESUME_MS) this.userTurnSeen = true }
      else { this.loudMs = 0; if (this.userTurnSeen) { this.quietMs += ms; if (this.quietMs >= TURN_END_MS) this.userTurnEnded() } }
    }
    const frame = this.snapshot.muted ? new Float32Array(samples.length) : samples
    this.pending.push(frame)
    this.pendingLength += frame.length
    while (this.pendingLength >= FRAME_SAMPLES) {
      const out = new Float32Array(FRAME_SAMPLES)
      let filled = 0
      while (filled < FRAME_SAMPLES) {
        const head = this.pending[0]!
        const take = Math.min(head.length, FRAME_SAMPLES - filled)
        out.set(head.subarray(0, take), filled)
        filled += take
        if (take === head.length) this.pending.shift()
        else this.pending[0] = head.subarray(take)
      }
      this.pendingLength -= FRAME_SAMPLES
      this.enqueueFrame(pcm16(out))
    }
  }

  private enqueueFrame(bytes: Uint8Array): void {
    const liveId = this.liveId
    if (liveId === undefined) return
    const seq = this.seq++
    this.sendChain = this.sendChain.then(async () => {
      for (let attempt = 0; attempt < 20; attempt++) {
        if (this.liveId !== liveId) return
        const response = await fetch(`${PREFIX}/live/append?liveId=${encodeURIComponent(liveId)}&seq=${seq}`, { method: 'POST', credentials: 'include', headers: { 'content-type': 'application/octet-stream' }, body: bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer }).catch(() => undefined)
        if (response?.ok) { this.set({ framesSent: this.snapshot.framesSent + 1 }); return }
        const status = response?.status
        if (status === 429 || status === 503) { await new Promise(r => setTimeout(r, 120)); continue }
        if (status === 410) return
        return
      }
    })
  }

  private openFeed(sessionId: string): void {
    const abort = new AbortController()
    this.feedAbort = abort
    void (async () => {
      const response = await fetch(`${PREFIX}/events?sessionId=${encodeURIComponent(sessionId)}`, { credentials: 'include', signal: abort.signal }).catch(() => undefined)
      if (!response?.body) return
      const reader = response.body.getReader()
      const decoder = new TextDecoder()
      let buffer = ''
      for (;;) {
        const { value, done } = await reader.read().catch(() => ({ value: undefined, done: true }))
        if (done) break
        buffer += decoder.decode(value, { stream: true })
        let newline = buffer.indexOf('\n')
        while (newline >= 0) {
          const line = buffer.slice(0, newline).trim()
          buffer = buffer.slice(newline + 1)
          if (line !== '') { try { this.onEvent(JSON.parse(line)) } catch { /* a malformed feed line is skipped; the next line is independent */ } }
          newline = buffer.indexOf('\n')
        }
      }
    })()
  }

  private onEvent(event: any): void {
    if (event.liveId !== undefined && event.liveId !== this.liveId) return
    switch (event.type) {
      case 'live.state':
        if (event.state === 'ready' && event.turn !== undefined) this.set({ turnReported: typeof event.turn === 'string' ? event.turn : event.turn?.mode ?? undefined })
        if (event.state === 'ready' && Array.isArray(event.warnings) && event.warnings.length > 0) this.set({ warnings: event.warnings.map((w: any) => String(w.code ?? w)) })
        if (event.state === 'closed' && this.snapshot.phase === 'live') { void this.teardown(); this.set({ phase: event.error ? 'error' : 'closed', error: event.error ? `${event.error.code ?? ''} ${event.error.message ?? ''}`.trim() : undefined }) }
        break
      case 'live.decision':
        if (event.decision === 'listen' || event.decision === 'speak' || event.decision === 'overlap') this.set({ decisions: this.trim([...this.snapshot.decisions, { at: performance.now(), decision: event.decision }]) })
        break
      case 'live.speech':
        if (event.event === 'started') {
          if (this.snapshot.waitingForUser) this.userTurnSeen = true
          this.set({ userSpeaking: true })
          if (this.activeResponse !== undefined && this.snapshot.turnMode === 'server-vad') this.bargeAt = performance.now()
        }
        if (event.event === 'stopped' || event.event === 'committed') {
          this.set({ userSpeaking: false })
          this.speechEndedAt = performance.now()
          if (this.userTurnSeen) this.userTurnEnded()
        }
        break
      case 'live.input.accepted':
        this.set({ framesAccepted: this.snapshot.framesAccepted + 1 })
        break
      case 'live.response': {
        const id = String(event.responseId)
        if (event.status === 'created' && this.snapshot.waitingForUser) { this.holdReply(id); break }
        if (event.status !== 'created' && this.activeResponse === id) { this.activeResponse = undefined; this.replyOpen = false; this.set({ responseActive: false }) }
        if (this.heldIds.has(id)) break
        if (event.status === 'created') { this.activeResponse = id; this.replyOpen = true; this.texts.set(id, ''); this.set({ responseActive: true }) }
        if (event.status === 'cancelled') {
          this.flushPlayback(id)
          this.markStopped(id)
          // Interrupted by speaking (server VAD): speech start → the server's cancellation.
          if (this.bargeAt !== undefined) {
            this.set({ interruptions: [...this.snapshot.interruptions, performance.now()], lastInterruptMs: Math.round(performance.now() - this.bargeAt) })
            this.bargeAt = undefined
          }
        }
        break
      }
      case 'audio.format': {
        const stream = this.streamFor(event.streamId)
        if (Number.isFinite(event.sampleRate)) stream.sampleRate = event.sampleRate
        break
      }
      case 'audio.chunk':
        if (this.heldIds.has(String(event.streamId))) break
        if (this.snapshot.waitingForUser && !this.streams.has(String(event.streamId))) { this.holdReply(String(event.streamId)); break }
        this.schedule(event)
        break
      case 'audio.epoch': {
        const stream = this.streams.get(event.streamId)
        if (stream !== undefined) { stream.epoch = event.epoch; this.flushPlayback(event.streamId) }
        break
      }
      case 'audio.end': {
        const stream = this.streams.get(event.streamId)
        if (stream !== undefined) stream.ended = true
        if (this.activeResponse === undefined || this.activeResponse === event.streamId) this.replyOpen = false
        if (event.status === 'cancelled') { this.flushPlayback(event.streamId); this.markStopped(event.streamId) }
        break
      }
      case 'text.delta': {
        const id = String(event.responseId ?? event.streamId)
        if (this.heldIds.has(id) || this.snapshot.caption?.responseId === id && this.snapshot.caption.stopped) break
        const text = (this.texts.get(id) ?? '') + String(event.text ?? '')
        this.texts.set(id, text)
        const caption = this.snapshot.caption
        if (caption !== undefined && caption.responseId !== id) this.set({ previousCaption: caption })
        this.set({ caption: { responseId: id, text, stopped: false } })
        break
      }
      default:
        break
    }
  }

  private streamFor(id: string): Stream {
    let stream = this.streams.get(id)
    if (stream === undefined) {
      stream = { id, sampleRate: 24000, epoch: 0, cursor: 0, playedBaseMs: 0, playedMs: 0, sources: new Set(), ended: false }
      this.streams.set(id, stream)
    }
    return stream
  }

  private schedule(event: any): void {
    const context = this.playbackContext
    if (context === undefined || typeof event.data !== 'string') return
    const stream = this.streamFor(String(event.streamId))
    if (Number.isFinite(event.epoch) && event.epoch < stream.epoch) return
    const binary = atob(event.data)
    const count = Math.floor(binary.length / 2)
    if (count === 0) return
    const buffer = context.createBuffer(1, count, stream.sampleRate)
    const channel = buffer.getChannelData(0)
    let energy = 0
    for (let i = 0; i < count; i++) {
      const v = (binary.charCodeAt(i * 2) | (binary.charCodeAt(i * 2 + 1) << 8)) << 16 >> 16
      channel[i] = v / 0x8000
      energy += channel[i]! * channel[i]!
    }
    const source = context.createBufferSource()
    source.buffer = buffer
    source.connect(context.destination)
    // An empty queue (first chunk, or the previous audio has run out) starts one buffer ahead; otherwise the chunk follows
    // the previous one without a break.
    const when = stream.cursor > context.currentTime + 0.01 ? stream.cursor : context.currentTime + this.bufferS
    // Silence between the end of the previous chunk and this one: an audible gap in the reply. Buffer more from now on.
    if (stream.startedAt !== undefined && stream.cursor > 0 && when > stream.cursor + 0.02) {
      this.bufferS = Math.min(PLAYBACK_BUFFER_MAX_S, this.bufferS + PLAYBACK_BUFFER_STEP_S)
      this.set({ playbackGaps: this.snapshot.playbackGaps + 1, playbackGapMs: this.snapshot.playbackGapMs + Math.round((when - stream.cursor) * 1000), playbackBufferMs: Math.round(this.bufferS * 1000) })
    }
    if (stream.startedAt === undefined) {
      stream.startedAt = when
      if (this.speechEndedAt !== undefined && stream.playedBaseMs === 0) {
        this.set({ firstAudioMs: Math.round(performance.now() - this.speechEndedAt + (when - context.currentTime) * 1000) })
        this.speechEndedAt = undefined
      }
    }
    source.start(when)
    stream.cursor = when + buffer.duration
    stream.sources.add(source)
    source.onended = () => { stream.sources.delete(source) }
    const level = Math.min(1, Math.sqrt(energy / count) * 5)
    const untilMs = performance.now() + (stream.cursor - context.currentTime) * 1000
    this.modelLevelUntil = Math.max(this.modelLevelUntil, untilMs)
    this.modelLevel = Math.max(this.modelLevel * 0.5, level)
    this.activeResponse = this.activeResponse ?? stream.id
    this.lastStreamId = stream.id
    if (!stream.ended) this.replyOpen = true
  }

  private flushPlayback(id: string): void {
    const stream = this.streams.get(id)
    if (stream === undefined) return
    const context = this.playbackContext
    if (context !== undefined) stream.playedBaseMs = this.heardMs(stream, context)
    for (const source of stream.sources) { try { source.stop() } catch { /* already stopped */ } }
    stream.sources.clear()
    stream.cursor = 0
    stream.startedAt = undefined
    this.modelLevelUntil = 0
  }

  /** Reply audio of `stream` actually played so far (before and since the last flush). */
  private heardMs(stream: Stream, context: AudioContext): number {
    const since = stream.startedAt === undefined ? 0 : Math.max(0, (Math.min(context.currentTime, stream.cursor) - stream.startedAt) * 1000)
    return Math.round(stream.playedBaseMs + since)
  }

  private markStopped(id: string): void {
    const caption = this.snapshot.caption
    if (caption?.responseId === id && !caption.stopped) this.set({ caption: { ...caption, stopped: true } })
  }

  private sendAcks(): void {
    const context = this.playbackContext
    const liveId = this.liveId
    if (context === undefined || liveId === undefined) return
    for (const stream of this.streams.values()) {
      const playedMs = this.heardMs(stream, context)
      if (playedMs <= stream.playedMs) continue
      stream.playedMs = playedMs
      void postJson(`${PREFIX}/live/control?liveId=${encodeURIComponent(liveId)}`, { type: 'playback-ack', responseId: stream.id, playedMs }).catch(() => {})
    }
  }

  private tick(): void {
    const now = performance.now()
    const audible = now < this.modelLevelUntil
    const speaking = audible || (this.replyOpen && this.modelLevelUntil > 0 && now < this.modelLevelUntil + SPEAKING_HOLD_MS)
    const sample: LevelSample = { at: now, user: this.snapshot.muted ? 0 : this.userLevel, model: audible ? Math.max(0.12, this.modelLevel) : 0 }
    this.userLevel *= 0.7
    this.set({ levels: this.trim([...this.snapshot.levels, sample]), speaking })
  }

  private trim<T extends { at: number }>(items: T[]): T[] {
    const cutoff = performance.now() - TIMELINE_KEEP_MS
    let start = 0
    while (start < items.length && items[start]!.at < cutoff) start++
    return start === 0 ? items : items.slice(start)
  }

  private async stopCapture(): Promise<void> {
    try { this.captureNode?.disconnect() } catch { /* already disconnected */ }
    for (const track of this.stream?.getTracks() ?? []) track.stop()
    await this.captureContext?.close().catch(() => {})
    this.captureNode = undefined
    this.captureContext = undefined
    this.stream = undefined
  }

  private async teardown(): Promise<void> {
    if (this.ackTimer !== undefined) clearInterval(this.ackTimer)
    if (this.tickTimer !== undefined) clearInterval(this.tickTimer)
    this.ackTimer = undefined
    this.tickTimer = undefined
    this.feedAbort?.abort()
    this.feedAbort = undefined
    await this.stopCapture()
    await this.playbackContext?.close().catch(() => {})
    this.playbackContext = undefined
    this.liveId = undefined
  }
}
