/**
 * Browser half of dsh-audio-release-kit (shared by Web and Desktop):
 * - `settings.plugin.item` card keyed `dsh-dgx-audio`: first-run audio server setup + explicit connection test;
 * - `conversation.input.left` chip: when an audio-adapter model is selected outside the no-tools audio preset,
 *   switch a blank session in place or start a new audio conversation in the same workspace with the same model;
 * - Voice conversation page (`sidebar.panellist` + `main`);
 * - `settings.onboarding`: the upstream Internal Testing Notice and DeepSeek API key steps are skipped (StartupDialogs.tsx).
 */

import { AudioModeChip, AUDIO_PRESET_ID, type AudioModeActions } from './AudioModeChip.tsx'
import { AudioServersCard, type AudioServersFace } from './AudioServersCard.tsx'
import { AudioRoutesStore } from './audio-routes.ts'
import { en, NS, zh } from './locale.ts'
import { SKIPPED_STARTUP_STEPS, SkipStartupStep, STARTUP_STEP_PRIORITY } from './StartupDialogs.tsx'
import { VoiceLiveSession } from './voice/live-session.ts'
import { VoiceIcon, VoicePage, type VoiceCandidate, type VoicePageFace } from './voice/VoicePage.tsx'

const SETTINGS_NS = 'dsh-dgx-audio'

function workspacePathOf(ctx: any, sessionId: string): string | undefined {
  const item = ctx.workspaces.list.getSnapshot().items?.find((entry: any) => entry.sessionIds?.includes(sessionId))
  return typeof item?.path === 'string' ? item.path : undefined
}

export const inject = [
  'slots', 'locale', 'settingsScope', 'sessions', 'workspaces', 'uiWorkspace',
  'remote', 'remote.agentPresets', 'remote.session', 'layout',
]

const VOICE_PANEL_ID = 'dsh-voice-conversation'

function unwrap<T>(result: { ok: boolean, value?: T, error?: { code?: string, message?: string } }, what: string): T {
  if (!result.ok) throw new Error(`${what}: ${result.error?.message ?? result.error?.code ?? 'failed'}`)
  return result.value as T
}

export function apply(ctx: any): void {
  ctx.effect(() => ctx.locale.register(NS, { en, zh }), 'audio-release-kit: dictionaries')

  for (const step of SKIPPED_STARTUP_STEPS) {
    ctx.slots.inject('settings.onboarding', () => ctx.slots.register({
      name: 'settings.onboarding',
      id: step.id,
      order: step.order,
      priority: STARTUP_STEP_PRIORITY,
    }, SkipStartupStep))
  }

  const routes = new AudioRoutesStore()
  void routes.refresh()
  ctx.effect(() => () => { routes.dispose() }, 'audio-release-kit: routes store')
  ctx.effect(() => ctx.remote.$on('settings/document-updated', () => { void routes.refresh() }), 'audio-release-kit: settings refresh')
  ctx.effect(() => ctx.remote.$on('llm/adapters-updated', () => { void routes.refresh() }), 'audio-release-kit: adapter refresh')
  ctx.effect(() => ctx.on('connection/reset', () => { void routes.refresh() }), 'audio-release-kit: reconnect refresh')

  const actions: AudioModeActions = {
    async switchBlank(sessionId) {
      unwrap(await ctx.remote.agentPresets.select(sessionId, AUDIO_PRESET_ID), 'select preset')
    },
    async startAudioConversation(sessionId, provider, model) {
      const workspace = ctx.workspaces.list.getSnapshot().items?.find((item: any) => item.sessionIds?.includes(sessionId))
      const summary = ctx.sessions.list.getSnapshot().byId?.[sessionId]
      let created: string
      if (workspace !== undefined) {
        created = await ctx.sessions.create({ workspaceId: workspace.workspaceId })
        unwrap(await ctx.remote.agentPresets.select(created, AUDIO_PRESET_ID), 'select preset')
      } else {
        // A session outside any workspace: create it on the host with the same directory and the audio preset,
        // then refresh the client list so it can be opened.
        const cwd: string | undefined = summary?.cwd ?? workspacePathOf(ctx, sessionId)
        const value = unwrap<{ sessionId: string }>(await ctx.remote.session.create({ ...(cwd !== undefined ? { cwd } : {}), agentPreset: AUDIO_PRESET_ID }), 'create session')
        created = value.sessionId
        await ctx.sessions.refresh()
      }
      unwrap(await ctx.remote.session.selectModel({ sessionId: created, provider, model }), 'select model')
      ctx.uiWorkspace.openSession(created)
    },
  }

  const scope = ctx.settingsScope.bind({ namespace: SETTINGS_NS })
  const serversFace: AudioServersFace = {
    scope: {
      getSnapshot: () => scope.getSnapshot(),
      subscribe: listener => scope.subscribe(listener),
      mutate: ops => scope.mutate(ops),
    },
    routes,
  }

  ctx.slots.inject('settings.plugin.item', () => ctx.slots.register({
    name: 'settings.plugin.item',
    key: SETTINGS_NS,
    locale: NS,
    inject: () => ({ audioServers: serversFace }),
  }, AudioServersCard))

  // Voice conversation page (iteration 1): sidebar panel entry + main view, audio-only live call.
  const voiceSession = new VoiceLiveSession()
  ctx.effect(() => () => { voiceSession.dispose() }, 'audio-release-kit: voice session')
  const voiceFace: VoicePageFace = {
    session: voiceSession,
    routes,
    async createSession(candidate: VoiceCandidate) {
      const items: any[] = ctx.workspaces.list.getSnapshot().items ?? []
      const workspace = items[0]
      let created: string
      if (workspace !== undefined) {
        created = await ctx.sessions.create({ workspaceId: workspace.workspaceId })
      } else {
        created = unwrap<{ sessionId: string }>(await ctx.remote.session.create({ agentPreset: AUDIO_PRESET_ID }), 'create session').sessionId
        await ctx.sessions.refresh()
      }
      unwrap(await ctx.remote.agentPresets.select(created, AUDIO_PRESET_ID), 'select preset')
      // The session model: a chat model of the same server when one exists, so the conversation can continue by text.
      const route = routes.getSnapshot().routes.find(r => r.provider === candidate.provider)
      const chat = route?.models.find(m => m.mode === 'chat')
      if (chat !== undefined) await ctx.remote.session.selectModel({ sessionId: created, provider: candidate.provider, model: chat.id }).catch(() => undefined)
      return created
    },
    openSession(sessionId: string) { ctx.uiWorkspace.openSession(sessionId) },
    openAudioModels() { ctx.layout.selectPanel('model-library') },
  }
  ctx.slots.inject('main', () => ctx.slots.register({ name: 'main', key: VOICE_PANEL_ID, locale: NS, inject: () => ({ voicePage: voiceFace }) }, VoicePage))
  ctx.slots.inject('sidebar.panellist', () => ctx.slots.register({
    name: 'sidebar.panellist',
    id: VOICE_PANEL_ID,
    order: 55,
    label: () => ctx.locale.bind(NS)('voiceNav'),
  }, VoiceIcon))

  ctx.slots.inject('conversation.input.left', () => ctx.slots.register({
    name: 'conversation.input.left',
    id: 'dsh-audio-mode-chip',
    order: 90,
    locale: NS,
    inject: () => ({ audioRoutes: routes, audioModeActions: actions }),
  }, AudioModeChip))
}
